// In SignUp.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../CSS/login.css'

function SignUp() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState(''); // Add a state variable for the username
  const navigate = useNavigate();

  const handleSubmit = (event) => {
    event.preventDefault();
    // Handle sign up logic here
    navigate('/'); // Navigate to the home page after successful sign up
  };

  return (
    <div>
      <h1>Sign Up</h1>
      <form onSubmit={handleSubmit}>
      <label htmlFor="username">Username:</label> {/* Add an input field for the username */}
        <input
          type="text"
          id="username"
          value={username}
          onChange={(event) => setUsername(event.target.value)}
        />
        <br/>
        <label htmlFor="email">Email:</label>
        <input
          type="email"
          id="email"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
        />
        <br />
        <label htmlFor="password">Password:</label>
        <input
          type="password"
          id="password"
          value={password}
          onChange={(event) => setPassword(event.target.value)}
        />
        <br />
        
        <br />
        <button type="submit">Sign Up</button>
      </form>
    </div>
  );
}

export default SignUp;

